use quince_core::types::Trade;use quince_indicators::{CustomIndicator,CustomIndicatorError,CustomIndicatorRegistration,IndicatorDescriptor,IndicatorInput,IndicatorOutput};static D:IndicatorDescriptor=IndicatorDescriptor{name:"custom_obv",input:IndicatorInput::Trade,output:IndicatorOutput::ScalarF64,parameters:&[]};pub static REGISTRATION:CustomIndicatorRegistration=CustomIndicatorRegistration{descriptor:&D,create};struct I{p:Option<f64>,v:f64}fn create(x:&[f64])->Result<Box<dyn CustomIndicator>,CustomIndicatorError>{if x.is_empty(){Ok(Box::new(I{p:None,v:0.}))}else{Err(CustomIndicatorError::Construction{indicator:D.name,reason:"accepts no parameters"})}}impl CustomIndicator for I{fn on_trade(&mut self,t:&Trade)->Option<f64>{if let Some(p)=self.p{if t.price>p{self.v+=t.qty}else if t.price<p{self.v-=t.qty}}self.p=Some(t.price);Some(self.v)}}
#[cfg(test)]mod tests{use super::*;use chrono::Utc;use quince_core::types::Side;fn t(p:f64)->Trade{Trade{price:p,qty:2.,time:Utc::now(),side:Side::Buy,trade_id:1}}#[test]fn obv(){let mut i=create(&[]).unwrap();i.on_trade(&t(1.));assert_eq!(i.on_trade(&t(2.)),Some(2.));}}
